-- =====================================================================
--  Módulo Áreas Verdes — registro en el portal + tabla + carga inicial.
--  Reporte geográfico de las áreas verdes del municipio (coordenadas del
--  listado oficial; NO requiere geocodificación).
--  Idempotente: re-ejecutar deja el mismo estado (recarga el catálogo).
-- =====================================================================
SET NAMES utf8mb4;
USE portal_qro;

-- 1) Registro del módulo -------------------------------------------------
VALUES ('areasverdes', 'Áreas Verdes',
        'Reporte geográfico de áreas verdes municipales · mapa, KPIs y listado',
        'tree', 'modules/areasverdes/index.php', '#2e9e5b', 7)
ON DUPLICATE KEY UPDATE
  nombre = VALUES(nombre), descripcion = VALUES(descripcion), icono = VALUES(icono),
  ruta = VALUES(ruta), color = VALUES(color), orden = VALUES(orden);

-- 2) Tabla del catálogo --------------------------------------------------
CREATE TABLE IF NOT EXISTS areas_verdes (
  id           INT UNSIGNED NOT NULL AUTO_INCREMENT,
  no_orig      INT UNSIGNED NULL COMMENT 'No. del listado original',
  nombre       VARCHAR(255) NOT NULL,
  delegacion   VARCHAR(120) NOT NULL,
  delegacion_norm VARCHAR(120) NOT NULL COMMENT 'MAYÚSCULAS sin acentos, para agrupar',
  lat          DECIMAL(10,7) NULL,
  lng          DECIMAL(10,7) NULL,
  puntos       JSON NULL COMMENT 'Todos los vértices [[lat,lng],...] cuando el área trae varios',
  n_puntos     TINYINT UNSIGNED NOT NULL DEFAULT 1,
  activo       TINYINT(1) NOT NULL DEFAULT 1,
  creado_en    TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (id),
  KEY idx_deleg (delegacion_norm),
  KEY idx_coord (lat, lng)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- 3) Carga inicial (idempotente: limpia y recarga) -----------------------
DELETE FROM areas_verdes;
ALTER TABLE areas_verdes AUTO_INCREMENT = 1;

